// A set of members sharing expenses, tracking each member's running net balance.
class Group {
    private final String groupId;                                              // unique id
    private final String name;                                                    // display name
    private final java.util.Set<String> memberIds = new java.util.HashSet<>();      // who belongs here
    private final java.util.Map<String, Double> netBalances = new java.util.HashMap<>(); // userId -> net balance

    public Group(String groupId, String name) {
        this.groupId = groupId; // store id
        this.name = name;         // store name
    }

    public String getGroupId() { return groupId; }               // id getter
    public void addMember(String userId) {                          // register a member
        memberIds.add(userId);                                          // add to membership set
        netBalances.putIfAbsent(userId, 0.0);                             // start at zero balance
    }
    public boolean isMember(String userId) { return memberIds.contains(userId); } // membership check
    public java.util.Set<String> getMemberIds() { return memberIds; }              // full member set
    public double getBalance(String userId) { return netBalances.getOrDefault(userId, 0.0); } // balance getter
    public void adjustBalance(String userId, double amount) { netBalances.merge(userId, amount, Double::sum); } // add or subtract balance
}

// One shared cost, who paid it, and how it splits among participants.
class Expense {
    private final String expenseId;                    // unique id, e.g. EXP1
    private final String groupId;                         // which group this belongs to
    private final String paidBy;                             // who paid the full amount
    private final double amount;                                // total expense amount
    private final java.util.Map<String, Double> splits;           // userId -> their share
    private final String description;                                // human readable label

