        this.expenseId = expenseId;     // store id
        this.groupId = groupId;           // store group
        this.paidBy = paidBy;               // store payer
        this.amount = amount;                 // store total
        this.splits = splits;                   // store per participant shares
        this.description = description;           // store label
    }

    public String getExpenseId() { return expenseId; } // id getter
    public String getPaidBy() { return paidBy; }          // payer getter
    public double getAmount() { return amount; }             // amount getter
    public java.util.Map<String, Double> getSplits() { return splits; } // splits getter
