// Strategy interface: how an expense divides among its participants.
interface SplitStrategy {
    java.util.Map<String, Double> computeSplits(double amount, java.util.List<String> participants, java.util.Map<String, Double> exactAmounts);
}

// Divides the amount evenly across every participant.
class EqualSplitStrategy implements SplitStrategy {
    @Override
    public java.util.Map<String, Double> computeSplits(double amount, java.util.List<String> participants, java.util.Map<String, Double> exactAmounts) {
        java.util.Set<String> unique = new java.util.LinkedHashSet<>(participants); // dedupe repeated participants
        double share = amount / unique.size();                                          // even share per person
        java.util.Map<String, Double> result = new java.util.HashMap<>();                   // userId -> share
        for (String userId : unique) result.put(userId, share);                                // assign the same share to everyone
        return result; // the computed equal splits
    }
}

// Uses caller supplied amounts, validated to sum to the expense total.
class ExactSplitStrategy implements SplitStrategy {
    @Override
    public java.util.Map<String, Double> computeSplits(double amount, java.util.List<String> participants, java.util.Map<String, Double> exactAmounts) {
        double sum = 0.0;                                          // running sum of supplied amounts
        for (double v : exactAmounts.values()) sum += v;               // add up every supplied share
        if (Math.abs(sum-amount) > 0.001) throw new InvalidSplitException("Exact splits sum to " + sum + " but expense total is " + amount); // must match
        return exactAmounts; // the caller supplied splits, now validated
    }
}

// Observer interface: reacts to expense lifecycle events.
interface ExpenseObserver {
    void onExpenseAdded(Expense expense);                      // an expense was accepted
    void onExpenseRejected(String groupId, String reason);       // an expense could not be added
    void onSettlementComputed(java.util.List<Settlement> settlements); // debts were simplified
}

// Simple observer that prints events to the console.
class ConsoleExpenseObserver implements ExpenseObserver {
    @Override
    public void onExpenseAdded(Expense expense) {
        System.out.println("Expense " + expense.getExpenseId() + " added: " + expense.getAmount() + " paid by " + expense.getPaidBy());
    }

    @Override
    public void onExpenseRejected(String groupId, String reason) {
        System.out.println("Expense rejected for group " + groupId + ": " + reason);
    }

    @Override
    public void onSettlementComputed(java.util.List<Settlement> settlements) {
        System.out.println("Computed " + settlements.size() + " settlement transactions");
    }
}

