using namespace std;

// Strategy interface: how an expense divides among its participants.
class SplitStrategy {
public:
    virtual map<string, double> computeSplits(double amount, vector<string> participants, map<string, double> exactAmounts) = 0;
    virtual ~SplitStrategy() {}
};

// Divides the amount evenly across every participant.
class EqualSplitStrategy : public SplitStrategy {
public:
    map<string, double> computeSplits(double amount, vector<string> participants, map<string, double> exactAmounts) override {
        set<string> unique(participants.begin(), participants.end()); // dedupe repeated participants
        double share = amount / unique.size();                            // even share per person
        map<string, double> result;                                          // userId -> share
        for (auto& userId : unique) result[userId] = share;                     // assign the same share to everyone
        return result; // the computed equal splits
    }
};

// Uses caller supplied amounts, validated to sum to the expense total.
class ExactSplitStrategy : public SplitStrategy {
public:
    map<string, double> computeSplits(double amount, vector<string> participants, map<string, double> exactAmounts) override {
        double sum = 0.0;                                            // running sum of supplied amounts
        for (auto& pair : exactAmounts) sum += pair.second;              // add up every supplied share
        if (abs(sum-amount) > 0.001) throw InvalidSplitException("Exact splits do not sum to the expense total"); // must match
        return exactAmounts; // the caller supplied splits, now validated
    }
};

// Observer interface: reacts to expense lifecycle events.
class ExpenseObserver {
public:
    virtual void onExpenseAdded(const Expense& expense) = 0;
    virtual void onExpenseRejected(const string& groupId, const string& reason) = 0;
    virtual void onSettlementComputed(const vector<Settlement>& settlements) = 0;
    virtual ~ExpenseObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleExpenseObserver : public ExpenseObserver {
public:
    void onExpenseAdded(const Expense& expense) override {
        cout << "Expense " << expense.expenseId << " added: " << expense.amount << " paid by " << expense.paidBy << endl;
    }
    void onExpenseRejected(const string& groupId, const string& reason) override {
        cout << "Expense rejected for group " << groupId << ": " << reason << endl;
    }
    void onSettlementComputed(const vector<Settlement>& settlements) override {
        cout << "Computed " << settlements.size() << " settlement transactions" << endl;
    }
};

