// Custom exceptions for the realistic failure modes.
class InvalidSplitException extends RuntimeException {
    public InvalidSplitException(String msg) { super(msg); }
}
class UserNotInGroupException extends RuntimeException {
    public UserNotInGroupException(String msg) { super(msg); }
}
class InvalidExpenseException extends RuntimeException {
    public InvalidExpenseException(String msg) { super(msg); }
}

// The core expense-sharing engine tying every piece together.
class SplitwiseService {
    private final java.util.Map<String, Group> groups = new java.util.HashMap<>();            // groupId -> Group
    private final java.util.Map<String, User> users = new java.util.HashMap<>();                 // userId -> User
    private final java.util.List<ExpenseObserver> observers = new java.util.ArrayList<>();          // listeners

    public void addUser(User user) { users.put(user.getUserId(), user); }              // register a user
    public void addGroup(Group group) { groups.put(group.getGroupId(), group); }          // register a group
    public void addObserver(ExpenseObserver observer) { observers.add(observer); }           // register a listener

    // Adds one shared expense to a group, validating membership and split totals before touching any balance.
    public synchronized Expense addExpense(String groupId, String paidBy, double amount, java.util.List<String> participants, SplitStrategy strategy, java.util.Map<String, Double> exactAmounts, ExpenseIdFactory factory) {
        Group group = groups.get(groupId);                                                 // the group this expense belongs to
        if (amount <= 0) {                                                                    // reject non-positive amounts
            for (ExpenseObserver obs : observers) obs.onExpenseRejected(groupId, "Invalid amount");
            throw new InvalidExpenseException("Amount must be positive");
        }
        if (!group.isMember(paidBy)) {                                                          // payer must be a member
            for (ExpenseObserver obs : observers) obs.onExpenseRejected(groupId, "Payer not in group");
            throw new UserNotInGroupException("Payer " + paidBy + " is not in group " + groupId);
        }
        for (String participant : participants) {                                                 // every participant must be a member
            if (!group.isMember(participant)) {
                for (ExpenseObserver obs : observers) obs.onExpenseRejected(groupId, "Participant not in group");
                throw new UserNotInGroupException("Participant " + participant + " is not in group " + groupId);
            }
        }
        java.util.Map<String, Double> splits = strategy.computeSplits(amount, participants, exactAmounts); // may throw InvalidSplitException
        String expenseId = factory.nextExpenseId();                                                 // build id
        group.adjustBalance(paidBy, amount);                                                          // payer is credited the full amount
        for (java.util.Map.Entry<String, Double> entry : splits.entrySet()) {                            // each participant is debited their share
            group.adjustBalance(entry.getKey(), -entry.getValue());
        }
        Expense expense = new Expense(expenseId, groupId, paidBy, amount, splits, "expense");         // build the record
        for (ExpenseObserver obs : observers) obs.onExpenseAdded(expense);                              // notify
        return expense; // hand back the recorded expense
    }

    // Greedily nets the group's largest creditor against its largest debtor until every balance reaches zero.
    public java.util.List<Settlement> simplifyDebts(String groupId) {
        Group group = groups.get(groupId);                                                    // the group to settle up
        java.util.List<double[]> creditors = new java.util.ArrayList<>();                         // placeholder, replaced below by proper maps
        java.util.Map<String, Double> balances = new java.util.HashMap<>();                          // working copy of every member's balance
        for (String memberId : group.getMemberIds()) balances.put(memberId, group.getBalance(memberId)); // snapshot balances
        java.util.List<Settlement> settlements = new java.util.ArrayList<>();                            // accumulated result

        while (true) {
            String maxCreditor = null;                                     // member with the largest positive balance
            String maxDebtor = null;                                          // member with the largest negative balance
            for (java.util.Map.Entry<String, Double> entry : balances.entrySet()) {
                if (maxCreditor == null || entry.getValue() > balances.get(maxCreditor)) maxCreditor = entry.getKey(); // track the largest creditor
                if (maxDebtor == null || entry.getValue() < balances.get(maxDebtor)) maxDebtor = entry.getKey();          // track the largest debtor
            }
            double creditAmount = balances.get(maxCreditor);                   // how much the creditor is owed
            double debtAmount = -balances.get(maxDebtor);                        // how much the debtor owes
            if (creditAmount < 0.001 || debtAmount < 0.001) break;                  // everyone is settled up
            double settleAmount = Math.min(creditAmount, debtAmount);                 // settle the smaller of the two
            settlements.add(new Settlement(maxDebtor, maxCreditor, settleAmount));       // record this payment
            balances.put(maxCreditor, creditAmount-settleAmount);                          // reduce the creditor's remaining balance
            balances.put(maxDebtor, -(debtAmount-settleAmount));                             // reduce the debtor's remaining balance
        }
        for (ExpenseObserver obs : observers) obs.onSettlementComputed(settlements);              // notify
        return settlements; // the minimal-effort list of payments
    }
}

