// The core expense-sharing engine tying every piece together.
class SplitwiseService {
    map<string, Group> groups;                          // groupId -> Group
    map<string, User> users;                               // userId -> User
    vector<shared_ptr<ExpenseObserver>> observers;            // listeners

public:
    void addUser(User user) { users[user.userId] = user; }              // register a user
    void addGroup(Group group) { groups[group.groupId] = group; }          // register a group
    void addObserver(shared_ptr<ExpenseObserver> observer) { observers.push_back(observer); } // register a listener
    double getBalance(string groupId, string userId) { return groups.at(groupId).getBalance(userId); } // balance lookup through the service, since groups are stored by value

    Expense addExpense(string groupId, string paidBy, double amount, vector<string> participants, shared_ptr<SplitStrategy> strategy, map<string, double> exactAmounts, ExpenseIdFactory& factory) {
        Group& group = groups.at(groupId);                                                    // the group this expense belongs to
        if (amount <= 0) {                                                                        // reject non-positive amounts
            for (auto& obs : observers) obs->onExpenseRejected(groupId, "Invalid amount");
            throw InvalidExpenseException("Amount must be positive");
        }
        if (!group.isMember(paidBy)) {                                                              // payer must be a member
            for (auto& obs : observers) obs->onExpenseRejected(groupId, "Payer not in group");
            throw UserNotInGroupException("Payer " + paidBy + " is not in group " + groupId);
        }
        for (auto& participant : participants) {                                                      // every participant must be a member
            if (!group.isMember(participant)) {
                for (auto& obs : observers) obs->onExpenseRejected(groupId, "Participant not in group");
                throw UserNotInGroupException("Participant " + participant + " is not in group " + groupId);
            }
        }
        map<string, double> splits = strategy->computeSplits(amount, participants, exactAmounts);       // may throw InvalidSplitException
        string expenseId = factory.nextExpenseId();                                                       // build id
        group.adjustBalance(paidBy, amount);                                                                // payer is credited the full amount
        for (auto& pair : splits) group.adjustBalance(pair.first, -pair.second);                              // each participant is debited their share
        Expense expense(expenseId, groupId, paidBy, amount, splits, "expense");                                 // build the record
        for (auto& obs : observers) obs->onExpenseAdded(expense);                                                 // notify
        return expense; // hand back the recorded expense
    }

    vector<Settlement> simplifyDebts(string groupId) {
        Group& group = groups.at(groupId);                                                     // the group to settle up
        map<string, double> balances;                                                             // working copy of every member's balance
        for (auto& memberId : group.memberIds) balances[memberId] = group.getBalance(memberId);       // snapshot balances
        vector<Settlement> settlements;                                                                 // accumulated result

        while (true) {
            string maxCreditor;                                       // member with the largest positive balance
            string maxDebtor;                                            // member with the largest negative balance
            bool first = true;                                              // tracks whether we have picked an initial candidate
            for (auto& pair : balances) {
                if (first || pair.second > balances[maxCreditor]) maxCreditor = pair.first; // track the largest creditor
                if (first || pair.second < balances[maxDebtor]) maxDebtor = pair.first;         // track the largest debtor
                first = false;
            }
            double creditAmount = balances[maxCreditor];                    // how much the creditor is owed
            double debtAmount = -balances[maxDebtor];                          // how much the debtor owes
            if (creditAmount < 0.001 || debtAmount < 0.001) break;                // everyone is settled up
            double settleAmount = min(creditAmount, debtAmount);                    // settle the smaller of the two
            settlements.push_back(Settlement(maxDebtor, maxCreditor, settleAmount));  // record this payment
            balances[maxCreditor] = creditAmount-settleAmount;                          // reduce the creditor's remaining balance
            balances[maxDebtor] = -(debtAmount-settleAmount);                             // reduce the debtor's remaining balance
        }
        for (auto& obs : observers) obs->onSettlementComputed(settlements);                 // notify
        return settlements; // the minimal-effort list of payments
    }
};

