class SplitwiseService {
    private final Map<String, Group> groups = new HashMap<>();
    private final Map<String, User> users = new HashMap<>();
    private final List<ExpenseObserver> observers = new ArrayList<>();

    public void addUser(User user) { users.put(user.getUserId(), user); }
    public void addGroup(Group group) { groups.put(group.getGroupId(), group); }
    public void addObserver(ExpenseObserver observer) { observers.add(observer); }

    public synchronized Expense addExpense(String groupId, String paidBy, double amount, List<String> participants, SplitStrategy strategy, Map<String, Double> exactAmounts, ExpenseIdFactory factory) {
        Group group = groups.get(groupId);
        if (amount <= 0) {
            for (ExpenseObserver obs : observers) obs.onExpenseRejected(groupId, "Invalid amount");
            throw new InvalidExpenseException("Amount must be positive");
        }
        if (!group.isMember(paidBy)) {
            for (ExpenseObserver obs : observers) obs.onExpenseRejected(groupId, "Payer not in group");
            throw new UserNotInGroupException("Payer " + paidBy + " is not in group " + groupId);
        }
        for (String participant : participants) {
            if (!group.isMember(participant)) {
                for (ExpenseObserver obs : observers) obs.onExpenseRejected(groupId, "Participant not in group");
                throw new UserNotInGroupException("Participant " + participant + " is not in group " + groupId);
            }
        }
        Map<String, Double> splits = strategy.computeSplits(amount, participants, exactAmounts);
        String expenseId = factory.nextExpenseId();
        group.adjustBalance(paidBy, amount);
        for (Map.Entry<String, Double> entry : splits.entrySet()) {
            group.adjustBalance(entry.getKey(), -entry.getValue());
        }
        Expense expense = new Expense(expenseId, groupId, paidBy, amount, splits, "expense");
        for (ExpenseObserver obs : observers) obs.onExpenseAdded(expense);
        return expense;
    }

    public List<Settlement> simplifyDebts(String groupId) {
        Group group = groups.get(groupId);
        Map<String, Double> balances = new HashMap<>();
        for (String memberId : group.getMemberIds()) balances.put(memberId, group.getBalance(memberId));
        List<Settlement> settlements = new ArrayList<>();

        while (true) {
            String maxCreditor = null;
            String maxDebtor = null;
            for (Map.Entry<String, Double> entry : balances.entrySet()) {
                if (maxCreditor == null || entry.getValue() > balances.get(maxCreditor)) maxCreditor = entry.getKey();
                if (maxDebtor == null || entry.getValue() < balances.get(maxDebtor)) maxDebtor = entry.getKey();
            }
            double creditAmount = balances.get(maxCreditor);
            double debtAmount = -balances.get(maxDebtor);
            if (creditAmount < 0.001 || debtAmount < 0.001) break;
            double settleAmount = Math.min(creditAmount, debtAmount);
            settlements.add(new Settlement(maxDebtor, maxCreditor, settleAmount));
            balances.put(maxCreditor, creditAmount-settleAmount);
            balances.put(maxDebtor, -(debtAmount-settleAmount));
        }
        for (ExpenseObserver obs : observers) obs.onSettlementComputed(settlements);
        return settlements;
    }
}

